@push('scripts')<script>$(function(){const t=$('#production-reports-table'),x=$.fn.dataTable.render.text(),classes={DRAFT:'app-status-neutral',RELEASED:'app-status-info',IN_PROGRESS:'app-status-warning',COMPLETED:'app-status-success',CANCELLED:'app-status-danger'},dt=t.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:t.data('url'),data:function(d){d.status=$('#report-status').val();d.date_from=$('#report-from').val();d.date_to=$('#report-to').val();}},order:[[1,'desc']],buttons:[window.erpExcelButton(t)],columns:[window.erpRowNumberColumn(),{data:'document_number',name:'document_number',render:function(v,z,r){return z==='display'?'<a href="'+x.display(r.show_url)+'">'+x.display(v)+'</a>':v;}},{data:'item_label',name:'item_label',render:x.display},{data:'quantity_label',name:'planned_quantity',className:'text-end',render:x.display},{data:'status_label',name:'status',render:function(v,z,r){return z==='display'?'<span class="badge '+(classes[r.status]||'app-status-neutral')+'">'+x.display(v)+'</span>':r.status;}},{data:'planned_finish_label',name:'planned_finish_date',render:x.display},{data:'duration_label',orderable:false,render:x.display},{data:null,orderable:false,searchable:false,className:'text-end',render:function(v,z,r){return z==='display'?'<a class="btn btn-sm btn-app-soft" href="'+x.display(r.show_url)+'" title="ดูรายละเอียด" aria-label="ดูรายละเอียด"><i class="bx bx-show" aria-hidden="true"></i></a>':'';}}]}));$('#production-report-filters').on('submit',function(e){e.preventDefault();dt.ajax.reload();});$('#report-reset').on('click',function(){$('#production-report-filters')[0].reset();dt.ajax.reload();});});</script>@endpush
